if hasattr(sys.stdout, "reconfigure"):
    try:
        sys.stdout.reconfigure(encoding="utf-8", errors="replace")
    except Exception:                                            # noqa: BLE001
        pass

UA = ("Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 "
      "(KHTML, like Gecko) Chrome/124.0 Safari/537.36")
MIN_BYTES = 5000

# —— 证据正则（2026-10-26 收紧：只认「声明句式」，不认「提到 SI 这个词」） ——
# 教训：旧版把裸词 `supplementary information` / `supplementary data` 也算声明，实测把
# 9 篇「讨论别人的 SI / 建议期刊改进 SI 格式 / 描述平台可提交 SI / 综述泛述」的文章判成 has_si，
# 于是被写进手动下载清单、白追一轮。
SI_DECL = re.compile(
    r"(?i)(supporting\s+information\s+is\s+available\s+free\s+of\s+charge"                 # ACS
    r"|data\s+needed\s+to\s+evaluate\s+the\s+conclusions.{0,80}(?:supporting|supplementary)\s+information"  # ACS/通用
    r"|(?:electronic\s+)?supplementary\s+information\s*(?:\(?\s*esi\s*\)?)?\s*[.:]?\s*available"  # RSC
    r"|\bESI\s+available"                                                                  # RSC 简写
    r"|supplementary\s+information\s+is\s+available"                                       # 通用/Nature
    r"|supplementary\s+materials?\s+(?:this\s+)?pdf\s+file\s+includes"                     # Science
    r"|supplementary\s+materials\s+science\.?org/doi"                                      # Science 章节
    r"|supplementary\s+material\s+for\s+this\s+article\s+is\s+available"                   # IOP
    r"|supplementary\s+information\s+available\s+at\s+https?://"                           # IOP
    r"|available\s+in\s+the\s+supplementary\s+material\s+of\s+this\s+article"              # Wiley 数据可得性
    r"|SI\s+Appendix"                                                                      # PNAS
    r"|the\s+online\s+version\s+contains\s+supplementary\s+material"                        # Springer/Nature 标准句
    r"|^\s*supplementary\s+information\s*[:：]"                                             # RSC/通用 标签式
    r"|^\s*(?:supporting|supplemental|supplementary)\s+information\s*$"                    # SI 小节标题（行首）
    r"|additional\s+supporting\s+information\s+is\s+available)", re.M)
# 仅用于展示上下文/统计「提到过 SI」，**不参与判定**
SI_MENTION = re.compile(r"(?i)(supplementar\w*|supporting\s+information)")
SI_REF = re.compile(r"(?i)\b(?:fig(?:ure)?s?\.?|table)\s*S\d+")
SUPP_FILE = re.compile(r"(?i)([A-Za-z]+\.?\d*-sup-\d{4}-[A-Za-z]+\.(?:docx|pdf|zip))")
PAGE_MARK = re.compile(r"<!--\s*page\s+\d+\s*-->")

ZIP_MAGIC = b"PK\x03\x04"


# ---------------------------------------------------------------- 判定层
def scan_text(pages):
    """从**逐页文本**判定 SI 存在性。

    pages: list[str]，第 i 项是第 i+1 页的文字。
    返回 dict：verdict（has_si / no_si / unknown）、decls、srefs、filenames、evidence。
    """
    pages = pages or []
    decls, refs, files, ev = [], 0, [], []
    for i, text in enumerate(pages, 1):
        t = text or ""
        for m in SI_DECL.finditer(t):
            s = max(0, m.start() - 70)
            e = min(len(t), m.end() + 170)
            frag = re.sub(r"\s+", " ", t[s:e]).strip()
            decls.append({"page": i, "text": frag})
            if len(ev) < 4:
                ev.append(f"p{i}: {frag[:180]}")
        refs += len(SI_REF.findall(t))
        for fn in SUPP_FILE.findall(t):
            if fn not in files:
                files.append(fn)
    total_chars = sum(len(p or "") for p in pages)

    if total_chars < 200:
        verdict = "unknown"
        ev.insert(0, f"文字层近乎为空（{total_chars} 字符）——可能是扫描件或非 PDF")
    elif decls or files or refs:
        verdict = "has_si"
    else:
        verdict = "no_si"
    return {"verdict": verdict, "decls": decls, "srefs": refs,
            "filenames": files, "evidence": ev, "chars": total_chars,
            "pages": len(pages)}


def scan_pdf(path, max_pages=600):
    """读取 PDF 并判定 SI。读不了返回 verdict=unknown（不当成"没有"）。"""
    try:
        import fitz  # PyMuPDF
    except Exception as e:                                       # noqa: BLE001
        return {"verdict": "unknown", "decls": [], "srefs": 0, "filenames": [],
                "evidence": [f"PyMuPDF 不可用：{type(e).__name__}: {e}"], "chars": 0, "pages": 0}
    try:
        doc = fitz.open(str(path))
    except Exception as e:                                       # noqa: BLE001
        return {"verdict": "unknown", "decls": [], "srefs": 0, "filenames": [],
                "evidence": [f"无法打开 PDF：{type(e).__name__}: {e}"], "chars": 0, "pages": 0}
    try:
        n = min(doc.page_count, max_pages)
        pages = [(doc[i].get_text() or "") for i in range(n)]
    finally:
        doc.close()
    out = scan_text(pages)
    if max_pages < len(pages):
        out["truncated"] = True
    return out


# ---------------------------------------------------------------- URL 层
def _q(s):
    return urllib.parse.quote(str(s), safe="")


def springer_urls(doi, year=None):
    """Nature/Springer 的 MediaObjects 直链。

    DOI 形如 10.1038/s41467-026-77517-w —— 注意 **026 是年份的 3 位截断**，
    必须用真实年份（卡片 `year:` 或 --year），否则 404。
    """
    d = (doi or "").strip()
    m = re.match(r"^10\.1038/([a-z]+)(\d+)-(\d{3})-(\d+)-([a-z0-9]+)$", d, re.I)
    if not m:
        return []
    _, journal, yy, third, _tail = m.groups()
    yrs = []
    if year:
        yrs.append(str(year))
    guess = 2000 + int(yy)
    if 2000 <= guess <= 2099 and str(guess) not in yrs:
        yrs.append(str(guess))
    # 🔴 DOI 第三段可能带前导零（`s41524-025-01573-x` → 文章号 1573），
    #    而 MediaObjects 文件名里**没有**这个零。实测（2026-10-24）：
    #    `41524_2025_01573_MOESM1_ESM.pdf` → 403，`41524_2025_1573_...` → 200（40.9 MB）。
    #    两种都试，先原样（对 `44615` 这类本来无零的 DOI 少一次无用请求）。
    arts = [third]
    try:
        stripped = str(int(third))
    except ValueError:
        stripped = third
    if stripped != third:
        arts.append(stripped)
    out = []
    for y in yrs:
        for art in arts:
            for n in (1, 2):
                out.append((f"https://static-content.springer.com/esm/art%3A10.1038%2F{_q(d.split('/', 1)[1])}"
                            f"/MediaObjects/{journal}_{y}_{art}_MOESM{n}_ESM.pdf",
                            f"Springer MediaObjects MOESM{n}（{y}）"))
    suffix = d.split("/", 1)[1]
    out.append((f"https://www.nature.com/articles/{suffix}_MOESM1_ESM.pdf", "nature.com 旧通道"))
    return out


def resolve_pii(doi, timeout=25):
    """Crossref → Elsevier PII（`resource.primary.URL` 里的 /pii/ 段）。"""
    u = "https://api.crossref.org/works/" + _q(doi)
    try:
        req = urllib.request.Request(u, headers={"User-Agent": UA})
        with urllib.request.urlopen(req, timeout=timeout) as r:
            msg = (json.loads(r.read().decode("utf-8")) or {}).get("message") or {}
    except Exception:                                            # noqa: BLE001
        return ""
    url = (((msg.get("resource") or {}).get("primary") or {}).get("URL") or "")
    m = re.search(r"/pii/(S[0-9A-Za-z]+)", url, re.I)
    return m.group(1) if m else ""


def elsevier_urls(pii):
    base = f"https://ars.els-cdn.com/content/image/1-s2.0-{pii}-mmc"
    return [(f"{base}{n}.{ext}", f"Elsevier mmc{n}.{ext}")
            for n in (1, 2, 3) for ext in ("pdf", "docx", "xlsx")]


def wiley_urls(doi, filenames):
    return [(f"https://onlinelibrary.wiley.com/action/downloadSupplement?doi={_q(doi)}&file={_q(fn)}",
             f"Wiley downloadSupplement {fn}") for fn in (filenames or [])]


def si_urls(doi, year=None, filenames=(), resolve=True):
    """按出版商给出候选直链（去重保序）。resolve=False 时不联网取 PII（自检用）。"""
    d = (doi or "").strip()
    if not d:
        return []
    out = []
    low = d.lower()
    if low.startswith("10.1038/"):
        out += springer_urls(d, year)
    if low.startswith("10.1016/") and resolve:
        pii = resolve_pii(d)
        if pii:
            out += elsevier_urls(pii)
    if low.startswith("10.1002/"):
        out += wiley_urls(d, filenames)
    # 通用兜底（多数对脚本 403，但有总比没有；浏览器里可点）
    out.append((f"https://onlinelibrary.wiley.com/doi/suppl/{_q(d)}", "Wiley SI 页（通用）"))
    out.append((f"https://pubs.acs.org/doi/suppl/{_q(d)}", "ACS SI 专题页（通用）"))
    seen, res = set(), []
    for u, note in out:
        if u not in seen:
            seen.add(u)
            res.append((u, note))
    return res


# ---------------------------------------------------------------- 取回层
def guess_kind(buf, ctype=""):
    """按魔数判真伪（Content-Type 会被 Cloudflare 页骗，故不以它为准）。"""
    if not buf or len(buf) <= MIN_BYTES:
        return ""
    if buf[:4] == b"%PDF":
        return "pdf"
    if buf[:4] == ZIP_MAGIC:
        if b"word/" in buf[:4096]:
            return "docx"
        ct = (ctype or "").lower()
        if "spreadsheet" in ct or "excel" in ct:
            return "xlsx"
        return "docx"
    return ""


def _atomic_write(path, buf):
    d = os.path.dirname(os.path.abspath(path))
    os.makedirs(d, exist_ok=True)
    fd, tmp = tempfile.mkstemp(dir=d, prefix=".part-")
    try:
        with os.fdopen(fd, "wb") as f:
            f.write(buf)
            f.flush()
            os.fsync(f.fileno())
        os.replace(tmp, path)
    except Exception:
        try:
            os.unlink(tmp)
        except OSError:
            pass
        raise


def default_si_dir():
    try:
        sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
        import kb_lib as K
        cfg = K.load_lit_config()
        pdf_dir = (cfg.get("paths") or {}).get("pdf_dir") or ""
        return os.path.join(pdf_dir, "si") if pdf_dir else ""
    except Exception:                                            # noqa: BLE001
        return ""


def scan_text_file(path, max_chars=600000):
    """从**已提取的全文 md**判定 SI（无 PDF 的卡片走这条路）。

    与 `scan_pdf` 口径一致：优先按 `<!-- page N -->` 标记**逐页**切分
    （证据里能给出页码）；无分页标记时整份文本当一「页」（`pages=1`）。
    `chars` 是全文字符数——不是页数。
    """
    try:
        raw = open(path, "rb").read().decode("utf-8", "replace")
    except Exception as e:                                       # noqa: BLE001
        return {"verdict": "unknown", "decls": [], "srefs": 0, "filenames": [],
                "evidence": [f"无法读取文本：{type(e).__name__}: {e}"],
                "chars": 0, "pages": 0}
    raw = raw.replace("\r\n", "\n").replace("\r", "\n")[:max_chars]
    marks = list(PAGE_MARK.finditer(raw))
    if marks:
        pages = []
        starts = [0] + [m.end() for m in marks]
        ends = [m.start() for m in marks] + [len(raw)]
        for s, e in zip(starts, ends):
            pages.append(raw[s:e])
    else:
        pages = [raw]
    out = scan_text(pages)
    out["source"] = "text"
    return out


def _acquire(info, doi, stem, si_dir, year, apply, timeout, verbose, res):
    """共用的下载层：候选直链 → 校验魔数 → 落盘。不判定 SI、不猜 DOI。"""
    urls = si_urls(doi, year=year, filenames=info.get("filenames") or [])
    if not urls:
        res["status"] = "missing"
        res["reason"] = "该出版商无可推导的 SI 直链"
        return res
    si_dir = si_dir or default_si_dir()
    if not si_dir:
        res["status"] = "missing"
        res["reason"] = "未配置 SI 落点（paths.pdf_dir）"
        return res
    for u, note in urls:
        try:
            req = urllib.request.Request(u, headers={"User-Agent": UA})
            with urllib.request.urlopen(req, timeout=timeout) as r:
                buf = r.read()
                ctype = r.headers.get("Content-Type", "")
        except Exception as e:                                   # noqa: BLE001
            res["tried"].append((u, f"{type(e).__name__}"))
            if verbose:
                print(f"    · {note}: {type(e).__name__}")
            continue
        kind = guess_kind(buf, ctype)
        if not kind:
            res["tried"].append((u, f"非真文件（{len(buf)}B, {ctype[:40]}）"))
            if verbose:
                print(f"    · {note}: 非真文件（{len(buf)}B, {ctype[:40]}）")
            continue
        if kind in ("docx", "xlsx"):
            try:
                with zipfile.ZipFile(io.BytesIO(buf)) as z:
                    if z.testzip() is not None:
                        raise zipfile.BadZipFile("CRC 校验失败")
            except Exception as e:                               # noqa: BLE001
                res["tried"].append((u, f"OOXML 损坏：{type(e).__name__}"))
                continue
        dest = os.path.join(si_dir, f"{stem}.si.{kind}")
        if apply:
            _atomic_write(dest, buf)
        res.update({"status": "present", "written": bool(apply), "file": dest,
                    "url": u, "kind": kind, "bytes": len(buf)})
        if verbose:
            # 干跑时**不得**说「已获取」——那句话会让人误以为文件已在盘上。
            verb = "已获取" if apply else "可获取（干跑未写盘）"
            print(f"    📎 SI {verb}：{os.path.basename(dest)}"
                  f"（{len(buf)/1e6:.1f} MB, {note}）")
        return res
    res["status"] = "missing"
    res["reason"] = f"{len(urls)} 个候选直链均未取到真文件"
    return res


def fetch(pdf_path, si_dir="", year=None, apply=False, timeout=30, verbose=True, doi=""):
    """判定 + 尝试下载。返回 dict（status: present / missing / no_si / unknown）。

    🔴 2026-10-23：`apply` 默认值由 True 改为 **False**（干跑）。
       `status: present` 表示「**能**取到真文件」，不表示「已经写盘」——
       是否落盘看返回值的 `written`。库函数默认写盘是危险缺省：任何新调用方
       （哪怕只是想探一下有没有 SI）都会静默往 references/SI 落文件。
       现网唯一调用方 `lit_fetch.py` 本就显式传 `apply=True`，行为不变。

    `doi`：可选覆盖。**卡片 frontmatter 的 DOI 优先于 PDF 文字层**——
      实测 Science/APS 的 PDF 版式里有 DOI 却抽不出（2026-10-24：6/6 篇 AAAS 报
      「未从 PDF 识别出 DOI」），而卡片里本来就有正确 DOI。给 `doi` 就不再猜。
    """
    pdf_path = os.path.abspath(pdf_path)
    info = scan_pdf(pdf_path)
    res = {"pdf": pdf_path, "scan": info, "status": "", "file": "", "tried": []}
    if info["verdict"] == "no_si":
        res["status"] = "no_si"
        return res
    if doi and doi.strip():
        res["doi"] = doi.strip()
        res["doi_source"] = "caller"
    else:
        res["doi"] = detect_doi(pdf_path)
        res["doi_source"] = "pdf"
    if not res["doi"]:
        res["status"] = "missing"
        res["reason"] = "未从 PDF 中识别出 DOI，无法生成候选直链"
        return res
    stem = os.path.splitext(os.path.basename(pdf_path))[0]
    return _acquire(info, res["doi"], stem, si_dir, year, apply, timeout, verbose, res)


def fetch_text(text_path, doi, si_dir="", year=None, apply=False, timeout=30,
               verbose=True):
    """无 PDF 时用**已提取全文**判定 + 下载；DOI 必须由调用方给（卡片 frontmatter）。

    与 `fetch` 的唯一差别是输入与 DOI 来源：PDF 版从文字层推 DOI，
    这里**不猜**——卡片没有 `doi:` 就返回 missing（候选直链无从构造）。
    落盘名与主文同 stem，故 `lit_ingest` 仍按 `<stem>.si.<kind>` 找得到。
    """
    text_path = os.path.abspath(text_path)
    info = scan_text_file(text_path)
    res = {"text": text_path, "scan": info, "status": "", "file": "", "tried": [],
           "doi": (doi or "").strip()}
    if info["verdict"] == "no_si":
        res["status"] = "no_si"
        return res
    if not res["doi"]:
        res["status"] = "missing"
        res["reason"] = "卡片无 DOI，无法生成候选直链（不猜）"
        return res
    stem = os.path.splitext(os.path.basename(text_path))[0]
    return _acquire(info, res["doi"], stem, si_dir, year, apply, timeout, verbose, res)


DOI_IN_TEXT = re.compile(r"\b10\.\d{4,9}/[^\s\"'<>()\[\]]+", re.I)


def detect_doi(pdf_path, max_pages=2):
    """从 PDF 前几页文字里找 DOI（取出现频次最高者）。"""
    try:
        import fitz
        doc = fitz.open(str(pdf_path))
        text = "\n".join((doc[i].get_text() or "") for i in range(min(max_pages, doc.page_count)))
        doc.close()
    except Exception:                                            # noqa: BLE001
        return ""
    cands = [c.rstrip(".,;") for c in DOI_IN_TEXT.findall(text)]
    if not cands:
        return ""
    best, bestn = "", 0
    for c in cands:
        n = cands.count(c)
        if n > bestn or (n == bestn and len(c) > len(best)):
            best, bestn = c, n
    return best


# ---------------------------------------------------------------- 自检
def selftest():
    ok = True

    def chk(cond, label):
        nonlocal ok
        print(f"  [{'ok' if cond else 'FAIL'}] {label}")
        ok = ok and bool(cond)

    print("— 判定（正例）—")
    r = scan_text(["x" * 300 + " The Supporting Information is available free of charge at https://pubs.acs.org/doi/10.1021/jacs.6c04230"])
    chk(r["verdict"] == "has_si" and r["decls"], "ACS 句式 → has_si")
    r = scan_text(["x" * 300 + " SupportingFile: anie74927-sup-0001-SuppMat.docx"])
    chk(r["verdict"] == "has_si" and r["filenames"] == ["anie74927-sup-0001-SuppMat.docx"], "Wiley SupportingFile → has_si + 文件名")
    # 「S1–S2」里只有带 Fig./Table 前缀的 S1 计入；srefs=2（Table S1、Figures S1）
    r = scan_text(["x" * 300 + " see Table S1 and Figures S1–S2 for details"])
    chk(r["verdict"] == "has_si" and r["srefs"] >= 2, "仅 S-编号引用 → has_si")
    r = scan_text(["x" * 300 + " Supplementary material for this article is available online"])
    chk(r["verdict"] == "has_si", "IOP/JES 句式 → has_si")
    r = scan_text(["x" * 300 + " Electronic supplementary information (ESI) available: Tables S1–S3"])
    chk(r["verdict"] == "has_si", "RSC ESI 句式 → has_si")

    print("— 判定（反例，必须判 no_si）—")
    r = scan_text(["y" * 400])
    chk(r["verdict"] == "no_si", "纯正文 400 字 → no_si")
    r = scan_text(["y" * 400 + " These results supporting the hypothesis are listed in Table 1 and Fig. 2."])
    chk(r["verdict"] == "no_si", "『supporting the hypothesis』+ Table 1 不得误判")
    r = scan_text(["y" * 400 + " The supplementary angle equals 30 degrees."])
    chk(r["verdict"] == "no_si", "『supplementary angle』不得误判")
    r = scan_text(["y" * 400 + " Refer to Table 2 for the comparison."])
    chk(r["verdict"] == "no_si", "普通 Table 2 不得误判")

    print("— 反例（2026-10-26 实证的 7 条「提到 SI 但本文没有」必须判 no_si）—")
    for frag, label in [
        ("results are substantive enough to include in published material (e.g. in Supporting Information files)",
         "建议把负结果写进 SI 文件（发表规范讨论）"),
        ("publishers have the opportunity to improve the situation, perhaps through enabling Supporting Information formats",
         "建议出版社支持 SI 格式"),
        ("This figure is reproduced from the Supporting Information of ref 94.",
         "引用他人论文的 SI"),
        ("Papers, patents, supplementary information, lab logs, recipes, standards, ontologies",
         "把 SI 当作数据来源之一列举"),
        ("are often scattered across main text, supplementary information, and laboratory logs.",
         "数据散落在正文与补充材料（泛述）"),
        ("which are often available upon request or published as supplementary data [6, 101-107].",
         "文献数据常以 supplementary data 发表（指他人）"),
        ("It will also allow users to submit supplementary information about materials",
         "平台允许用户提交 SI（功能描述）"),
    ]:
        r = scan_text(["z" * 400 + " " + frag])
        chk(r["verdict"] == "no_si", "「%s」→ no_si" % label)

    print("— 正例（2026-10-26 核查确认的出版商固定声明，不得漏）—")
    for frag, label in [
        ("Additional information Supplementary information is available for this paper.", "Nature 附加信息"),
        ("The data that support the findings of this study are available in the supplementary material of this article.",
         "Wiley 数据可得性"),
        ("SUPPLEMENTARY MATERIALS science.org/doi/10.1126/science.aef5487", "Science 章节"),
        ("SI Appendix", "PNAS SI Appendix"),
        ("SupportingFile: adma74644-sup-0001-SuppMat.pdf", "Wiley SupportingFile"),
        ("Supplementary Information", "SI 小节标题（行首独立成行）"),
        ("The online version contains supplementary material available at https://doi.org/10.1038/s41524-023-01003-w",
         "Springer/Nature 标准句"),
        ("Supplementary information: See DOI for details", "RSC 标签式"),
    ]:
        r = scan_text(["w" * 400 + "\n" + frag])
        chk(r["verdict"] == "has_si", "「%s」→ has_si" % label)

    print("— 未知（不得当成没有）—")
    r = scan_text([""])
    chk(r["verdict"] == "unknown", "空文字层 → unknown")
    r = scan_text(["short"])
    chk(r["verdict"] == "unknown", "过短文字 → unknown")

    print("— URL 构造 —")
    u = springer_urls("10.1038/s41467-026-77517-w", year=2026)
    chk(any("41467_2026_77517_MOESM1_ESM.pdf" in x for x, _ in u), "Springer：年份来自参数而非 DOI 的 026")
    chk(not springer_urls("10.1038/nature12345"), "老式 Nature DOI 不硬造 URL")
    # 前导零：DOI 写 01573，MediaObjects 里是 1573（2026-10-24 实测两种都试的必要性）
    u = springer_urls("10.1038/s41524-025-01573-x", year=2025)
    chk(any("41524_2025_1573_MOESM1_ESM.pdf" in x for x, _ in u),
        "Springer：DOI 第三段带前导零时，同时生成去掉零的文件名")
    chk(any("41524_2025_01573_MOESM1_ESM.pdf" in x for x, _ in u),
        "Springer：原样文件名也保留（不能只留一种）")
    u = springer_urls("10.1038/s41467-023-44615-y", year=2024)
    chk(not any("_044615_" in x for x, _ in u), "无前导零的 DOI 不得生成去零变体")
    w = wiley_urls("10.1002/anie.1466065", ["anie74927-sup-0001-SuppMat.docx"])
    chk(w and "downloadSupplement" in w[0][0] and "anie74927" in w[0][0], "Wiley：文件名进入直链")
    e = elsevier_urls("S0012345678900123")
    chk(any("mmc1.docx" in x for x, _ in e), "Elsevier：mmc 多扩展名枚举")
    chk(si_urls("", resolve=False) == [], "空 DOI → 无候选")

    print("— 魔数闸门 —")
    chk(guess_kind(b"%PDF-1.7" + b"0" * 6000, "text/html") == "pdf", "真 PDF（哪怕 CT 是 html）")
    chk(guess_kind(b"<html>" + b"0" * 6000, "application/pdf") == "", "HTML 冒充 PDF 必须判空")
    chk(guess_kind(ZIP_MAGIC + b"0" * 6000, "application/vnd.openxmlformats-officedocument.wordprocessingml.document") == "docx", "docx 魔数")
    chk(guess_kind(b"%PDF-1.7", "") == "", "过小文件判空")

    print("— 无 PDF 路径（--text 模式）—")
    # ⚠️ 不要用 tempfile.mkdtemp：本机沙箱下它建出的目录**连创建者都不能写**
    #    （kb_lib 头部有完整根因）。统一走 kb_lib.make_temp_dir 的逐级回退。
    sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
    try:
        import kb_lib as _K
        _tmpd = _K.make_temp_dir(prefix="lit_si_st_")
        _cleanup = lambda: _K.remove_temp_dir(_tmpd)             # noqa: E731
    except Exception:                                            # noqa: BLE001
        import tempfile as _tf
        import shutil as _sh
        _tmpd = _tf.mkdtemp(prefix="lit_si_st_")
        _cleanup = lambda: _sh.rmtree(_tmpd, ignore_errors=True)  # noqa: E731
    try:
        p1 = os.path.join(_tmpd, "has.md")
        with open(p1, "w", encoding="utf-8") as f:
            f.write("x" * 400 + "\nThe Supporting Information is available free of charge.\n")
        r = scan_text_file(p1)
        chk(r["verdict"] == "has_si" and r.get("source") == "text",
            "全文 md 里有 SI 声明 → has_si")
        p2 = os.path.join(_tmpd, "none.md")
        with open(p2, "w", encoding="utf-8") as f:
            f.write("y" * 500)
        chk(scan_text_file(p2)["verdict"] == "no_si", "全文 md 无声明 → no_si")
        chk(scan_text_file(os.path.join(_tmpd, "absent.md"))["verdict"] == "unknown",
            "文本不存在 → unknown（不得当成『没有』）")
        # 无 DOI 时**不得猜**、不得联网
        r = fetch_text(p1, "", si_dir=_tmpd)
        chk(r["status"] == "missing" and "无 DOI" in (r.get("reason") or ""),
            "--text 无 DOI → missing（不猜、不联网）")
        r = fetch_text(p2, "10.1038/s41467-026-77517-w", si_dir=_tmpd)
        chk(r["status"] == "no_si", "判定 no_si 的文本即便给了 DOI 也不下载")
        chk(all(x.endswith(".md") for x in os.listdir(_tmpd)), "干跑不得写盘")
    finally:
        _cleanup()

    print("\n" + ("lit_si selftest: PASS" if ok else "lit_si selftest: FAIL"))
    return 0 if ok else 1


# ---------------------------------------------------------------- CLI
def main(argv=None):
    ap = argparse.ArgumentParser(description="SI 存在性判定 / 自动获取（本工具链）")
    sub = ap.add_subparsers(dest="cmd")

    sp = sub.add_parser("scan", help="判定一篇 PDF 有没有 SI")
    sp.add_argument("pdf", nargs="?")
    sp.add_argument("--text", default="", help="改判已提取的全文 md（无 PDF 时用）")
    sp.add_argument("--json", action="store_true")

    fp = sub.add_parser("fetch", help="判定并尝试下载 SI")
    fp.add_argument("pdf", nargs="?")
    fp.add_argument("--text", default="", help="从已提取全文判定（无 PDF 时用；须配 --doi）")
    fp.add_argument("--doi", default="", help="卡片 frontmatter 的 DOI（--text 模式必填）")
    fp.add_argument("--si-dir", default="")
    fp.add_argument("--year", default="")
    fp.add_argument("--apply", action="store_true", help="真正写盘（默认干跑）")
    fp.add_argument("--timeout", type=int, default=30)
    fp.add_argument("--json", action="store_true")

    sub.add_parser("selftest", help="自检（已知答案反算）")
    # ⚠️ `kb_toolcheck.py` 对所有工具一律调 `--selftest`（带横线）。
    #    只提供 `selftest` 子命令时，自检在本库里其实从未被它跑到过——
    #    2026-10-22 实测报 `unrecognized arguments: --selftest`。两种写法都收。
    ap.add_argument("--selftest", action="store_true", help="自检（等价于 selftest 子命令）")

    args = ap.parse_args(argv)
    if args.cmd == "selftest" or getattr(args, "selftest", False):
        return selftest()
    if not args.cmd:
        ap.print_help()
        return 2

    target = args.text or args.pdf
    if not target:
        print("给了 scan/fetch 但没给文件：请给位置参数 <pdf> 或 --text <md>", file=sys.stderr)
        return 2
    if not os.path.isfile(target):
        print(f"不是文件：{target}", file=sys.stderr)
        return 2

    if args.cmd == "scan":
        r = scan_text_file(target) if args.text else scan_pdf(target)
        if args.json:
            print(json.dumps(r, ensure_ascii=False, indent=2))
        else:
            print(f"文件：{target}")
            print(f"页数：{r.get('pages')}  文字量：{r.get('chars')} 字符")
            print(f"判定：{r['verdict']}   声明的 SI 语句：{len(r['decls'])} 处"
                  f"   S-编号引用：{r['srefs']} 处   文件名：{r['filenames'] or '—'}")
            for e in r["evidence"][:4]:
                print(f"  - {e}")
        return 0

    if args.text:
        if not args.doi:
            print("--text 模式必须给 --doi（卡片 frontmatter 的 DOI，不从全文猜）",
                  file=sys.stderr)
            return 2
        r = fetch_text(args.text, args.doi, si_dir=args.si_dir, year=args.year or None,
                       apply=args.apply, timeout=args.timeout)
    else:
        r = fetch(args.pdf, si_dir=args.si_dir, year=args.year or None,
                  apply=args.apply, timeout=args.timeout, doi=args.doi)
    if args.json:
        print(json.dumps(r, ensure_ascii=False, indent=2))
    else:
        st = {"present": "✅ 已取到", "missing": "⚠️ 有 SI 但没取到（须进手动下载清单）",
              "no_si": "⛔ 判定无 SI（不必下载）", "unknown": "❓ 无法判定"}.get(r["status"], r["status"])
        if r["status"] == "present" and not args.apply:
            # 「已取到」在干跑下是**假话**——文件没落盘。分开表述，避免误以为可跳过 --apply。
            st = "✅ 可获取（干跑未写盘）"
        print(f"判定：{r['scan']['verdict']}   结果：{st}")
        if r.get("reason"):
            print(f"原因：{r['reason']}")
        if r["status"] == "present" and not args.apply:
            print("（干跑：未写盘；加 --apply 落盘）")
    return 0 if r["status"] in ("present", "no_si") else 4


if __name__ == "__main__":
    sys.exit(main())
